1	package com.example.starter.cosmetic.service;
2	
3	import com.example.starter.cosmetic.domain.AgeBandRule;
4	import com.example.starter.cosmetic.domain.ChangeType;
5	import com.example.starter.cosmetic.domain.ChildBandDossier;
6	import com.example.starter.cosmetic.domain.ChildSafetyReportRecord;
7	import com.example.starter.cosmetic.domain.FilingCategory;
8	import com.example.starter.cosmetic.domain.FilingRecord;
9	import com.example.starter.cosmetic.domain.FilingStatus;
10	import com.example.starter.cosmetic.domain.FormulationIngredient;
11	import com.example.starter.cosmetic.domain.ReviewDetail;
12	import com.example.starter.cosmetic.domain.TestReportRecord;
13	import com.example.starter.cosmetic.port.ActiveSlot;
14	import com.example.starter.cosmetic.port.FilingPort;
15	import com.example.starter.cosmetic.port.CatalogPort;
16	import com.example.starter.cosmetic.port.IdempotencyPort;
17	import com.example.starter.cosmetic.port.IdempotencyRow;
18	import com.example.starter.cosmetic.port.ReportPort;
19	import com.example.starter.cosmetic.support.FingerprintSupport;
20	import com.example.starter.cosmetic.support.JsonSupport;
21	import com.example.starter.cosmetic.web.dto.AgeRuleResponse;
22	import com.example.starter.cosmetic.web.dto.ChangeFilingRequest;
23	import com.example.starter.cosmetic.web.dto.ChildBandDossierRequest;
24	import com.example.starter.cosmetic.web.dto.ChildEvidenceResponse;
25	import com.example.starter.cosmetic.web.dto.CorrectionFilingRequest;
26	import com.example.starter.cosmetic.web.dto.FilingResponse;
27	import com.example.starter.cosmetic.web.dto.FilingResultResponse;
28	import com.example.starter.cosmetic.web.dto.FormulationItemRequest;
29	import com.example.starter.cosmetic.web.dto.SubmitFilingRequest;
30	import com.example.starter.cosmetic.web.dto.TestReportRequest;
31	import com.example.starter.cosmetic.web.dto.ReviewDetailResponse;
32	import org.springframework.dao.DataIntegrityViolationException;
33	import org.springframework.stereotype.Service;
34	import org.springframework.transaction.annotation.Transactional;
35	
36	import java.time.Clock;
37	import java.time.Instant;
38	import java.time.LocalDate;
39	import java.time.ZoneOffset;
40	import java.util.ArrayList;
41	import java.util.LinkedHashMap;
42	import java.util.List;
43	import java.util.Map;
44	import java.util.Optional;
45	
46	/**
47	 * 备案领域服务默认实现。
48	 *
49	 * <p>所有写操作以 requestId 幂等：指纹覆盖 requestId 与全部业务字段，
50	 * 同键同参返回首次结果（idempotentReplay=true），同键异参 409；
51	 * 业务/版本/幂等结果同事务，参数或状态异常整体回滚，失败不占键。</p>
52	 *
53	 * <p>儿童备案（filingCategory=CHILD）：提交/补正/变更均同步分龄审查，
54	 * 受理时冻结报告清单、分龄规则版本与标识文本摘要；材料补正生成新修订并
55	 * 使旧修订待审批准失效（同事务），公示只能使用最新修订。</p>
56	 */
57	@Service
58	public class FilingServiceImpl implements FilingService {
59	
60	    private static final String OP_SUBMIT = "SUBMIT";
61	    private static final String OP_CHANGE = "CHANGE";
62	    private static final String OP_WITHDRAW = "WITHDRAW";
63	    private static final String OP_CORRECT = "CORRECT";
64	    private static final int PUBLIC_NOTICE_DAYS = 10;
65	    private static final long IDEMPOTENCY_WAIT_NANOS = 10_000_000_000L;
66	    private static final long IDEMPOTENCY_WAIT_STEP_MS = 20L;
67	
68	    private final FilingPort filingPort;
69	    private final CatalogPort catalogPort;
70	    private final ReportPort reportPort;
71	    private final IdempotencyPort idempotencyPort;
72	    private final PublicNoticeEffector publicNoticeEffector;
73	    private final Clock clock;
74	    private final FormReviewEvaluator formReviewEvaluator;
75	    private final ChildFormReviewEvaluator childFormReviewEvaluator;
76	
77	    public FilingServiceImpl(FilingPort filingPort,
78	                             CatalogPort catalogPort,
79	                             ReportPort reportPort,
80	                             IdempotencyPort idempotencyPort,
81	                             PublicNoticeEffector publicNoticeEffector,
82	                             Clock clock) {
83	        this.filingPort = filingPort;
84	        this.catalogPort = catalogPort;
85	        this.reportPort = reportPort;
86	        this.idempotencyPort = idempotencyPort;
87	        this.publicNoticeEffector = publicNoticeEffector;
88	        this.clock = clock;
89	        this.formReviewEvaluator = new FormReviewEvaluator(catalogPort);
90	        this.childFormReviewEvaluator = new ChildFormReviewEvaluator(catalogPort, reportPort);
91	    }
92	
93	    private Instant now() {
94	        return clock.instant();
95	    }
96	
97	    // ============================ 备案提交 ============================
98	
99	    @Override
100	    @Transactional
101	    public FilingResultResponse submit(SubmitFilingRequest request) {
102	        Instant now = now();
103	        boolean child = request.isChild();
104	        validateSubmitChildFields(request, child);
105	
106	        Map<String, Object> fingerprintFields = new LinkedHashMap<>();
107	        fingerprintFields.put("requestId", request.requestId());
108	        fingerprintFields.put("productCode", request.productCode());
109	        fingerprintFields.put("productName", request.productName());
110	        fingerprintFields.put("formulation", request.formulation());
111	        fingerprintFields.put("claims", request.claims());
112	        fingerprintFields.put("reports", request.reports() == null ? List.of() : request.reports());
113	        fingerprintFields.put("filingCategory", child ? "CHILD" : "ADULT");
114	        fingerprintFields.put("ageLowerMonths", request.ageLowerMonths());
115	        fingerprintFields.put("ageUpperMonths", request.ageUpperMonths());
116	        fingerprintFields.put("childDossiers",
117	                request.childDossiers() == null ? List.of() : request.childDossiers());
118	        String fingerprint = FingerprintSupport.sha256(fingerprintFields);
119	
120	        Optional<FilingResultResponse> replay =
121	                resolveIdempotency(request.requestId(), OP_SUBMIT, fingerprint);
122	        if (replay.isPresent()) {
123	            return replay.get();
124	        }
125	
126	        List<FormulationIngredient> formulation = request.formulation().stream()
127	                .map(i -> new FormulationIngredient(i.code(), i.name(), i.concentrationPct()))
128	                .toList();
129	        List<String> claims = List.copyOf(request.claims());
130	        List<TestReportRecord> reports = registerReports(request.reports());
131	        List<ChildBandDossier> dossiers = registerChildDossiers(request.childDossiers());
132	
133	        int versionNo = filingPort.nextProductVersion(request.productCode());
134	        String filingNo = allocateFilingNo();
135	        LocalDate submitDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
136	
137	        FormReviewEvaluator.Result review;
138	        String ageRuleVersion = null;
139	        String labelDigest = null;
140	        if (child) {
141	            ageRuleVersion = catalogPort.currentAgeRuleVersion();
142	            List<AgeBandRule> bands = catalogPort.listAgeBands(ageRuleVersion);
143	            labelDigest = labelDigestOf(dossiers);
144	            review = childFormReviewEvaluator.evaluate(request.productName(), formulation, claims,
145	                    request.ageLowerMonths(), request.ageUpperMonths(), dossiers, bands,
146	                    ageRuleVersion, now, filingNo, versionNo);
147	        } else {
148	            review = formReviewEvaluator.evaluate(
149	                    request.productName(), formulation, claims, reports, submitDate, now, filingNo, versionNo);
150	        }
151	
152	        List<ReviewDetail> details = new ArrayList<>(review.details());
153	        // 注销后新宣称审查一律拒绝（独立规则，可复算）
154	        boolean postWithdrawalBlocked = filingPort.hasWithdrawnRecord(request.productCode());
155	        if (postWithdrawalBlocked) {
156	            details.add(new ReviewDetail(null, filingNo, versionNo, FormReviewEvaluator.STAGE_FORM,
157	                    "POST_WITHDRAWAL_NEW_CLAIM_REJECTED", false,
158	                    "该产品存在已注销备案，注销后新宣称审查一律拒绝", now));
159	        }
160	        // 同一产品存在未终态（在途/有效）备案时，不得再次新提交
161	        boolean inflightBlocked = hasInFlightFiling(request.productCode());
162	        if (inflightBlocked) {
163	            details.add(new ReviewDetail(null, filingNo, versionNo, FormReviewEvaluator.STAGE_FORM,
164	                    "PRODUCT_ALREADY_IN_FLIGHT", false,
165	                    "同一产品已存在公示/异议审查/生效中的备案，应通过变更接口办理", now));
166	        }
167	
168	        boolean passed = review.passed() && !postWithdrawalBlocked && !inflightBlocked;
169	        List<String> reasons = new ArrayList<>(review.reasons());
170	        if (postWithdrawalBlocked) {
171	            reasons.add("[POST_WITHDRAWAL_NEW_CLAIM_REJECTED] 注销后新宣称审查一律拒绝");
172	        }
173	        if (inflightBlocked) {
174	            reasons.add("[PRODUCT_ALREADY_IN_FLIGHT] 同一产品只允许一个在途/有效备案");
175	        }
176	
177	        FilingStatus status = passed ? FilingStatus.PUBLIC : FilingStatus.FORM_REJECTED;
178	        LocalDate noticeDate = passed ? submitDate : null;
179	        Instant expiresAt = passed ? publicExpiry(noticeDate) : null;
180	
181	        // 受理冻结：儿童备案冻结报告清单、分龄规则版本与标识文本摘要（含审查未通过修订，便于证据复算）
182	        FilingRecord record = new FilingRecord(
183	                null, filingNo, request.productCode(), request.productName(), versionNo, null,
184	                ChangeType.INITIAL, status, formulation, claims, reports, null,
185	                request.requestId(), now, now, noticeDate, expiresAt, null,
186	                null, null, passed ? null : String.join("；", reasons),
187	                child ? FilingCategory.CHILD : FilingCategory.ADULT,
188	                child ? request.ageLowerMonths() : null,
189	                child ? request.ageUpperMonths() : null,
190	                ageRuleVersion, child ? dossiers : null, labelDigest);
191	
192	        filingPort.saveReviews(details);
193	        filingPort.insert(record);
194	
195	        FilingRecord saved = filingPort.findLatestByNo(filingNo).orElseThrow();
196	        FilingResultResponse response = buildResult(saved, details, false, now);
197	        idempotencyPort.complete(request.requestId(), 200, status.name(), filingNo,
198	                JsonSupport.toJson(response), now);
199	        return response;
200	    }
201	
202	    /** 提交参数的儿童字段一致性校验（非法参数 400）。 */
203	    private void validateSubmitChildFields(SubmitFilingRequest request, boolean child) {
204	        if (child) {
205	            validateAgeRange(request.ageLowerMonths(), request.ageUpperMonths());
206	            return;
207	        }
208	        if (request.ageLowerMonths() != null || request.ageUpperMonths() != null
209	                || (request.childDossiers() != null && !request.childDossiers().isEmpty())) {
210	            throw new IllegalArgumentException(
211	                    "成人备案不得携带儿童字段（年龄范围/分龄档材料）；儿童备案请显式 filingCategory=CHILD");
212	        }
213	    }
214	
215	    /** 申请年龄范围参数校验：整数月闭区间，0≤下限≤上限≤144（非法参数 400）。 */
216	    private void validateAgeRange(Integer ageLower, Integer ageUpper) {
217	        if (ageLower == null || ageUpper == null) {
218	            throw new IllegalArgumentException("儿童备案必须提供申请年龄上下限（整数月）");
219	        }
220	        if (ageLower < 0 || ageUpper > ChildFormReviewEvaluator.MAX_AGE_MONTHS || ageLower > ageUpper) {
221	            throw new IllegalArgumentException(String.format(
222	                    "申请年龄范围非法：[%d, %d]月，须满足 0≤下限≤上限≤%d",
223	                    ageLower, ageUpper, ChildFormReviewEvaluator.MAX_AGE_MONTHS));
224	        }
225	    }
226	
227	    // ============================ 儿童材料补正 ============================
228	
229	    @Override
230	    @Transactional
231	    public FilingResultResponse correct(String filingNo, CorrectionFilingRequest request) {
232	        Instant now = now();
233	        Map<String, Object> fingerprintFields = new LinkedHashMap<>();
234	        fingerprintFields.put("requestId", request.requestId());
235	        fingerprintFields.put("filingNo", filingNo);
236	        fingerprintFields.put("expectedVersion", request.expectedVersion());
237	        fingerprintFields.put("productName", request.productName());
238	        fingerprintFields.put("formulation", request.formulation());
239	        fingerprintFields.put("claims", request.claims());
240	        fingerprintFields.put("reports", request.reports());
241	        fingerprintFields.put("packagingText", request.packagingText());
242	        fingerprintFields.put("ageLowerMonths", request.ageLowerMonths());
243	        fingerprintFields.put("ageUpperMonths", request.ageUpperMonths());
244	        fingerprintFields.put("childDossiers", request.childDossiers());
245	        String fingerprint = FingerprintSupport.sha256(fingerprintFields);
246	
247	        Optional<FilingResultResponse> replay = resolveIdempotency(request.requestId(), OP_CORRECT, fingerprint);
248	        if (replay.isPresent()) {
249	            return replay.get();
250	        }
251	
252	        FilingRecord current = filingPort.findLatestByNo(filingNo)
253	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
254	        if (!current.isChild()) {
255	            throw new UnprocessableException("NOT_CHILD_FILING",
256	                    "备案 " + filingNo + " 非儿童备案，不支持材料补正");
257	        }
258	        if (current.status() != FilingStatus.FORM_REJECTED) {
259	            throw new UnprocessableException("CORRECTION_NOT_ALLOWED",
260	                    "仅待补正（形式审查未通过）的最新修订可补正，当前状态: " + current.status());
261	        }
262	        if (!request.expectedVersion().equals(current.versionNo())) {
263	            throw new ConflictException("VERSION_CONFLICT",
264	                    "expectedVersion=" + request.expectedVersion()
265	                            + " 与当前最新版本 " + current.versionNo() + " 不一致（409）");
266	        }
267	
268	        String newName = request.productName() == null ? current.productName() : request.productName();
269	        List<FormulationIngredient> newFormulation = request.formulation() == null
270	                ? current.formulation()
271	                : request.formulation().stream()
272	                .map(i -> new FormulationIngredient(i.code(), i.name(), i.concentrationPct())).toList();
273	        List<String> newClaims = request.claims() == null ? current.claims() : List.copyOf(request.claims());
274	        List<TestReportRecord> newReports = request.reports() == null
275	                ? current.reports()
276	                : registerReports(request.reports());
277	        String newPackaging = request.packagingText() == null
278	                ? current.packagingText()
279	                : request.packagingText();
280	        Integer newAgeLower = request.ageLowerMonths() == null
281	                ? current.ageLowerMonths() : request.ageLowerMonths();
282	        Integer newAgeUpper = request.ageUpperMonths() == null
283	                ? current.ageUpperMonths() : request.ageUpperMonths();
284	        List<ChildBandDossier> newDossiers = request.childDossiers() == null
285	                ? current.childDossiers()
286	                : registerChildDossiers(request.childDossiers());
287	        validateAgeRange(newAgeLower, newAgeUpper);
288	
289	        int versionNo = current.versionNo() + 1;
290	        String ageRuleVersion = catalogPort.currentAgeRuleVersion();
291	        List<AgeBandRule> bands = catalogPort.listAgeBands(ageRuleVersion);
292	        String labelDigest = labelDigestOf(newDossiers);
293	
294	        FormReviewEvaluator.Result review = childFormReviewEvaluator.evaluate(
295	                newName, newFormulation, newClaims, newAgeLower, newAgeUpper, newDossiers,
296	                bands, ageRuleVersion, now, filingNo, versionNo);
297	
298	        boolean passed = review.passed();
299	        FilingStatus status = passed ? FilingStatus.PUBLIC : FilingStatus.FORM_REJECTED;
300	        LocalDate noticeDate = passed ? LocalDate.ofInstant(now, ZoneOffset.UTC) : null;
301	        Instant expiresAt = passed ? publicExpiry(noticeDate) : null;
302	
303	        // 同事务：旧修订（待补正）待审批准失效，补正生成新修订；公示只能使用最新修订
304	        filingPort.supersedeRejectedRevisions(filingNo, now);
305	        FilingRecord record = new FilingRecord(
306	                null, filingNo, current.productCode(), newName, versionNo, current.parentFilingNo(),
307	                current.changeType(), status, newFormulation, newClaims, newReports, newPackaging,
308	                request.requestId(), now, now, noticeDate, expiresAt, null,
309	                null, null, passed ? null : String.join("；", review.reasons()),
310	                FilingCategory.CHILD, newAgeLower, newAgeUpper,
311	                ageRuleVersion, newDossiers, labelDigest);
312	        filingPort.saveReviews(review.details());
313	        filingPort.insert(record);
314	
315	        FilingRecord saved = filingPort.findVersion(filingNo, versionNo).orElseThrow();
316	        FilingResultResponse response = buildResult(saved, review.details(), false, now);
317	        idempotencyPort.complete(request.requestId(), 200, status.name(), filingNo,
318	                JsonSupport.toJson(response), now);
319	        return response;
320	    }
321	
322	    // ============================ 备案变更 ============================
323	
324	    @Override
325	    @Transactional
326	    public FilingResultResponse change(String productCode, ChangeFilingRequest request) {
327	        Instant now = now();
328	        Map<String, Object> fingerprintFields = new LinkedHashMap<>();
329	        fingerprintFields.put("requestId", request.requestId());
330	        fingerprintFields.put("productCode", productCode);
331	        fingerprintFields.put("productName", request.productName());
332	        fingerprintFields.put("formulation", request.formulation());
333	        fingerprintFields.put("claims", request.claims());
334	        fingerprintFields.put("reports", request.reports());
335	        fingerprintFields.put("packagingText", request.packagingText());
336	        fingerprintFields.put("expectedVersion", request.expectedVersion());
337	        fingerprintFields.put("filingCategory", request.filingCategory());
338	        fingerprintFields.put("ageLowerMonths", request.ageLowerMonths());
339	        fingerprintFields.put("ageUpperMonths", request.ageUpperMonths());
340	        fingerprintFields.put("childDossiers", request.childDossiers());
341	        String fingerprint = FingerprintSupport.sha256(fingerprintFields);
342	
343	        Optional<FilingResultResponse> replay = resolveIdempotency(request.requestId(), OP_CHANGE, fingerprint);
344	        if (replay.isPresent()) {
345	            return replay.get();
346	        }
347	
348	        ActiveSlot slot = filingPort.findActiveSlot(productCode)
349	                .orElseThrow(() -> new ConflictException("NO_ACTIVE_FILING",
350	                        "产品当前无有效备案，无法变更（可能尚未生效或已注销）: " + productCode));
351	        FilingRecord current = filingPort.findVersion(slot.filingNo(), slot.versionNo())
352	                .orElseThrow(() -> new IllegalStateException("有效槽指向版本不存在"));
353	        if (current.status() != FilingStatus.EFFECTIVE) {
354	            throw new ConflictException("ACTIVE_FILING_NOT_EFFECTIVE",
355	                    "当前有效槽备案状态异常: " + current.status());
356	        }
357	
358	        boolean childInvolved = current.isChild()
359	                || "CHILD".equals(request.filingCategory())
360	                || request.ageLowerMonths() != null || request.ageUpperMonths() != null
361	                || request.childDossiers() != null;
362	        if (childInvolved) {
363	            // 儿童备案变更必须携带 expectedVersion（乐观并发控制）
364	            if (request.expectedVersion() == null) {
365	                throw new IllegalArgumentException("儿童备案变更必须携带 expectedVersion（当前有效版本号）");
366	            }
367	            if (!request.expectedVersion().equals(current.versionNo())) {
368	                throw new ConflictException("VERSION_CONFLICT",
369	                        "expectedVersion=" + request.expectedVersion()
370	                                + " 与当前有效版本 " + current.versionNo() + " 不一致（409）");
371	            }
372	        }
373	
374	        // 上一实质变更新版本仍在公示/异议审查时，不允许叠加变更，避免多个在途版本竞争同一有效槽
375	        boolean anotherInFlight = filingPort.findByProduct(productCode).stream()
376	                .anyMatch(r -> r.id() != current.id()
377	                        && (r.status() == FilingStatus.PUBLIC
378	                        || r.status() == FilingStatus.OBJECTION_REVIEW));
379	        if (anotherInFlight) {
380	            throw new ConflictException("PREVIOUS_CHANGE_IN_PUBLICITY",
381	                    "该产品已有变更版本处于公示/异议审查中，须待其形成终态后再变更");
382	        }
383	
384	        String newName = request.productName() == null ? current.productName() : request.productName();
385	        List<FormulationIngredient> newFormulation = request.formulation() == null
386	                ? current.formulation()
387	                : request.formulation().stream()
388	                .map(i -> new FormulationIngredient(i.code(), i.name(), i.concentrationPct())).toList();
389	        List<String> newClaims = request.claims() == null ? current.claims() : List.copyOf(request.claims());
390	        List<TestReportRecord> newReports = request.reports() == null
391	                ? current.reports()
392	                : registerReports(request.reports());
393	        String newPackaging = request.packagingText() == null
394	                ? current.packagingText()
395	                : request.packagingText();
396	
397	        // 目标类别与儿童字段合并：显式 ADULT 视为清除儿童属性；显式 CHILD 必须提供年龄与材料
398	        FilingCategory newCategory;
399	        Integer newAgeLower;
400	        Integer newAgeUpper;
401	        List<ChildBandDossier> newDossiers;
402	        if ("ADULT".equals(request.filingCategory())) {
403	            newCategory = FilingCategory.ADULT;
404	            newAgeLower = null;
405	            newAgeUpper = null;
406	            newDossiers = null;
407	        } else if ("CHILD".equals(request.filingCategory())) {
408	            newCategory = FilingCategory.CHILD;
409	            newAgeLower = request.ageLowerMonths();
410	            newAgeUpper = request.ageUpperMonths();
411	            newDossiers = registerChildDossiers(request.childDossiers());
412	        } else {
413	            newCategory = current.filingCategory();
414	            newAgeLower = request.ageLowerMonths() == null
415	                    ? current.ageLowerMonths() : request.ageLowerMonths();
416	            newAgeUpper = request.ageUpperMonths() == null
417	                    ? current.ageUpperMonths() : request.ageUpperMonths();
418	            newDossiers = request.childDossiers() == null
419	                    ? current.childDossiers()
420	                    : registerChildDossiers(request.childDossiers());
421	        }
422	        if (newCategory == FilingCategory.CHILD) {
423	            validateAgeRange(newAgeLower, newAgeUpper);
424	        } else if (newAgeLower != null || newAgeUpper != null || newDossiers != null) {
425	            throw new IllegalArgumentException(
426	                    "成人备案不得保留儿童字段；转为儿童备案请显式 filingCategory=CHILD 并提供年龄范围与分龄档材料");
427	        }
428	
429	        boolean formulationChanged = !newFormulation.equals(current.formulation());
430	        boolean claimsChanged = !newClaims.equals(current.claims());
431	        boolean packagingChanged = !nullSafeEquals(newPackaging, current.packagingText());
432	        boolean nameChanged = !newName.equals(current.productName());
433	        boolean categoryChanged = newCategory != current.filingCategory();
434	        boolean ageChanged = !java.util.Objects.equals(newAgeLower, current.ageLowerMonths())
435	                || !java.util.Objects.equals(newAgeUpper, current.ageUpperMonths());
436	        boolean dossiersChanged = !java.util.Objects.equals(newDossiers, current.childDossiers());
437	
438	        if (!formulationChanged && !claimsChanged && !packagingChanged && !nameChanged
439	                && !categoryChanged && !ageChanged && !dossiersChanged) {
440	            throw new ConflictException("NO_CHANGE", "变更内容与当前有效备案完全一致，无需变更");
441	        }
442	
443	        int versionNo = filingPort.nextProductVersion(productCode);
444	
445	        // 儿童属性、年龄或标识适用范围（分龄档材料）改变一律实质变更，不得伪装为包装文字简易变更
446	        if (formulationChanged || claimsChanged || categoryChanged || ageChanged || dossiersChanged) {
447	            return substantiveChange(request.requestId(), current, productCode, newName, newFormulation,
448	                    newClaims, newReports, newPackaging, newCategory, newAgeLower, newAgeUpper,
449	                    newDossiers, versionNo, now);
450	        }
451	        return simpleChange(request.requestId(), current, productCode, newName, newFormulation,
452	                newClaims, newReports, newPackaging, versionNo, now);
453	    }
