455	    private FilingResultResponse substantiveChange(String requestId,
456	                                                   FilingRecord current,
457	                                                   String productCode,
458	                                                   String newName,
459	                                                   List<FormulationIngredient> newFormulation,
460	                                                   List<String> newClaims,
461	                                                   List<TestReportRecord> newReports,
462	                                                   String newPackaging,
463	                                                   FilingCategory newCategory,
464	                                                   Integer newAgeLower,
465	                                                   Integer newAgeUpper,
466	                                                   List<ChildBandDossier> newDossiers,
467	                                                   int versionNo,
468	                                                   Instant now) {
469	        String newFilingNo = allocateFilingNo();
470	        LocalDate submitDate = LocalDate.ofInstant(now, ZoneOffset.UTC);
471	
472	        FormReviewEvaluator.Result review;
473	        String ageRuleVersion = null;
474	        String labelDigest = null;
475	        if (newCategory == FilingCategory.CHILD) {
476	            ageRuleVersion = catalogPort.currentAgeRuleVersion();
477	            List<AgeBandRule> bands = catalogPort.listAgeBands(ageRuleVersion);
478	            labelDigest = labelDigestOf(newDossiers);
479	            review = childFormReviewEvaluator.evaluate(newName, newFormulation, newClaims,
480	                    newAgeLower, newAgeUpper, newDossiers, bands, ageRuleVersion,
481	                    now, newFilingNo, versionNo);
482	        } else {
483	            review = formReviewEvaluator.evaluate(
484	                    newName, newFormulation, newClaims, newReports, submitDate, now, newFilingNo, versionNo);
485	        }
486	
487	        boolean passed = review.passed();
488	        FilingStatus status = passed ? FilingStatus.PUBLIC : FilingStatus.FORM_REJECTED;
489	        LocalDate noticeDate = passed ? submitDate : null;
490	        Instant expiresAt = passed ? publicExpiry(noticeDate) : null;
491	
492	        FilingRecord record = new FilingRecord(
493	                null, newFilingNo, productCode, newName, versionNo, current.filingNo(),
494	                ChangeType.SUBSTANTIVE, status, newFormulation, newClaims, newReports, newPackaging,
495	                requestId, now, now, noticeDate, expiresAt, null, null, null,
496	                passed ? null : String.join("；", review.reasons()),
497	                newCategory,
498	                newCategory == FilingCategory.CHILD ? newAgeLower : null,
499	                newCategory == FilingCategory.CHILD ? newAgeUpper : null,
500	                ageRuleVersion,
501	                newCategory == FilingCategory.CHILD ? newDossiers : null,
502	                labelDigest);
503	        filingPort.saveReviews(review.details());
504	        filingPort.insert(record);
505	
506	        // 实质变更审查通过进入公示；旧备案在新版本生效前继续有效，待期满同事务切换。
507	        FilingRecord saved = filingPort.findLatestByNo(newFilingNo).orElseThrow();
508	        FilingResultResponse response = buildResult(saved, review.details(), false, now);
509	        idempotencyPort.complete(requestId, 200, status.name(), newFilingNo,
510	                JsonSupport.toJson(response), now);
511	        return response;
512	    }
