514	    private FilingResultResponse simpleChange(String requestId,
515	                                              FilingRecord current,
516	                                              String productCode,
517	                                              String newName,
518	                                              List<FormulationIngredient> newFormulation,
519	                                              List<String> newClaims,
520	                                              List<TestReportRecord> newReports,
521	                                              String newPackaging,
522	                                              int versionNo,
523	                                              Instant now) {
524	        // 包装文字类（含产品名称文字）简易变更：引用原备案编号，不重新公示，即时生效。
525	        // 儿童属性/年龄/标识适用范围变化已在变更入口判定为实质变更，不会进入本分支。
526	        FilingRecord record = new FilingRecord(
527	                null, current.filingNo(), productCode, newName, versionNo, current.filingNo(),
528	                ChangeType.SIMPLE, FilingStatus.EFFECTIVE, newFormulation, newClaims, newReports,
529	                newPackaging, requestId, now, now, null, null, null, now, null, null,
530	                current.filingCategory(), current.ageLowerMonths(), current.ageUpperMonths(),
531	                current.ageRuleVersion(), current.childDossiers(), current.labelDigest());
532	        filingPort.insert(record);
533	
534	        boolean superseded = filingPort.supersedeEffective(current.id(), now);
535	        if (!superseded) {
536	            // 并发下旧有效版本已被另一变更替代：本事务回滚，返回 409
537	            throw new ConflictException("FILING_ALREADY_CHANGED",
538	                    "当前有效版本已被其他变更替代，本次简易变更失败（唯一有效备案）");
539	        }
540	        filingPort.replaceSlot(productCode, current.filingNo(), versionNo, now);
541	
542	        List<ReviewDetail> details = List.of(new ReviewDetail(null, current.filingNo(), versionNo,
543	                FormReviewEvaluator.STAGE_FORM, "SIMPLE_CHANGE_NO_REVIEW", true,
544	                "仅包装文字类变更，走简易变更，引用原备案编号 " + current.filingNo()
545	                        + "，不重新形式审查与公示，即时生效", now));
546	        filingPort.saveReviews(details);
547	
548	        FilingRecord saved = filingPort.findVersion(current.filingNo(), versionNo).orElseThrow();
549	        FilingResultResponse response = buildResult(saved, details, false, now);
550	        idempotencyPort.complete(requestId, 200, FilingStatus.EFFECTIVE.name(), current.filingNo(),
551	                JsonSupport.toJson(response), now);
552	        return response;
553	    }
