557	    @Override
558	    @Transactional
559	    public FilingResultResponse acceptObjection(String filingNo, Instant atUtc, String reason) {
560	        Instant objectionAt = atUtc == null ? now() : atUtc;
561	        FilingRecord record = filingPort.findLatestByNo(filingNo)
562	                .orElseThrow(() -> new NotFoundException("备案不存在: " + filingNo));
563	        if (record.status() != FilingStatus.PUBLIC) {
564	            throw new ConflictException("NOT_IN_PUBLICITY",
565	                    "当前状态不受理公示异议: " + record.status()
566	                            + "（公示与异议竞争唯一终态，可能已期满生效）");
567	        }
568	        // 期满时刻之后到达的异议无效；恰期满时刻(==)允许与自动生效并发竞争，由原子更新判定唯一终态
569	        if (record.publicExpiresAtUtc() != null && objectionAt.isAfter(record.publicExpiresAtUtc())) {
570	            throw new ConflictException("PUBLICITY_ALREADY_EXPIRED",
571	                    "异议受理时刻(UTC)=" + objectionAt + " 晚于公示期满时刻(UTC)="
572	                            + record.publicExpiresAtUtc() + "，异议不再受理");
573	        }
574	        boolean accepted = filingPort.acceptObjectionIfPublic(record.id(), objectionAt);
575	        if (!accepted) {
576	            throw new ConflictException("PUBLICITY_ALREADY_EXPIRED",
577	                    "公示已期满生效，异议不再受理（唯一终态）");
578	        }
579	        ReviewDetail detail = new ReviewDetail(null, filingNo, record.versionNo(), "OBJECTION",
580	                "OBJECTION_ACCEPTED", true,
581	                "公示期内受理异议，受理时刻(UTC)=" + objectionAt + "，转入异议审查；原因=" + reason,
582	                objectionAt);
583	        filingPort.saveReviews(List.of(detail));
584	
585	        FilingRecord updated = filingPort.findById(record.id()).orElseThrow();
586	        return buildResult(updated, List.of(detail), false, objectionAt);
587	    }
