741	    // ============================ 辅助方法 ============================
742	
743	    private Optional<FilingResultResponse> resolveIdempotency(String requestId,
744	                                                              String operation,
745	                                                              String fingerprint) {
746	        Optional<IdempotencyRow> existing = idempotencyPort.find(requestId);
747	        if (existing.isEmpty()) {
748	            try {
749	                idempotencyPort.claim(requestId, operation, fingerprint);
750	                return Optional.empty();
751	            } catch (DataIntegrityViolationException e) {
752	                // 并发同键：另一个事务刚刚插入主张行，落入下方重读判定
753	                existing = idempotencyPort.find(requestId);
754	                if (existing.isEmpty()) {
755	                    throw e;
756	                }
757	            }
758	        }
759	        IdempotencyRow row = existing.orElseThrow();
760	        if (!row.operation().equals(operation)) {
761	            throw new ConflictException("IDEMPOTENCY_KEY_CROSSED_OPERATION",
762	                    "requestId 已用于其它操作类型: " + row.operation());
763	        }
764	        if (!row.fingerprint().equals(fingerprint)) {
765	            throw new ConflictException("IDEMPOTENCY_PARAM_MISMATCH",
766	                    "同一 requestId 对应不同业务参数，拒绝处理（409）");
767	        }
768	        // 同键同参但首个事务尚未回填（并发重放）：等待首个事务完成后返回首次结果
769	        if (row.httpStatus() == 0 || row.responseJson() == null || row.responseJson().isEmpty()) {
770	            row = awaitFirstCompletion(requestId);
771	        }
772	        FilingResultResponse first = JsonSupport.fromJson(row.responseJson(), FilingResultResponse.class);
773	        return Optional.of(new FilingResultResponse(first.httpStatus(), first.filing(),
774	                true, first.reviewDetails(), first.atUtc()));
775	    }
