832	    /**
833	     * 标识文本摘要：结构化（分龄档+文本逐项）规范化后取 SHA-256，
834	     * 合法文本含分隔符亦能被无歧义区分。
835	     */
836	    private String labelDigestOf(List<ChildBandDossier> dossiers) {
837	        Map<String, Object> fields = new LinkedHashMap<>();
838	        fields.put("kind", "CHILD_AGE_LABELS");
839	        fields.put("labels", (dossiers == null ? List.<ChildBandDossier>of() : dossiers).stream()
840	                .map(d -> {
841	                    Map<String, Object> entry = new LinkedHashMap<String, Object>();
842	                    entry.put("bandCode", d.bandCode());
843	                    entry.put("labelText", d.labelText());
844	                    return entry;
845	                }).toList());
846	        return FingerprintSupport.sha256(fields);
847	    }
848	
849	    private boolean hasInFlightFiling(String productCode) {
850	        return filingPort.findByProduct(productCode).stream()
851	                .anyMatch(r -> r.status() == FilingStatus.PUBLIC
852	                        || r.status() == FilingStatus.OBJECTION_REVIEW
853	                        || r.status() == FilingStatus.EFFECTIVE
854	                        || r.status() == FilingStatus.SUBMITTED);
855	    }
856	
857	    private String allocateFilingNo() {
858	        long seq = filingPort.nextFilingSequence();
859	        return String.format("SYN-F-%06d", seq);
860	    }
861	
862	    /**
863	     * 公示期满口径：起算日 D（UTC）起 10 个自然日，恰第 10 日 24:00 期满，
864	     * 即 D+10 日 00:00:00 UTC（到期判定使用 &lt;=，恰期满当时即可生效）。
865	     */
866	    private Instant publicExpiry(LocalDate noticeDateUtc) {
867	        return noticeDateUtc.plusDays(PUBLIC_NOTICE_DAYS)
868	                .atStartOfDay().toInstant(ZoneOffset.UTC);
869	    }
870	
871	    private FilingResultResponse buildResult(FilingRecord record,
872	                                             List<ReviewDetail> details,
873	                                             boolean replay,
874	                                             Instant atUtc) {
875	        List<ReviewDetailResponse> detailResponses = details.stream()
876	                .map(ReviewDetailResponse::from).toList();
877	        return new FilingResultResponse(200, FilingResponse.from(record), replay,
878	                detailResponses, atUtc);
879	    }
880	
881	    private static boolean nullSafeEquals(String a, String b) {
882	        return a == null ? b == null : a.equals(b);
883	    }
